(4301866, 619293, 84438, '<td valign="top">Very nice, but might be a bit better without the overall blue cast.</td>', 'Very nice, but might be a bit better without the overall blue cast.', '2007-12-08 16:27:04.000000', NULL, 1),
(4301868, 619541, 46885, '<td valign="top">...where?</td>', '...where?', '2007-12-08 16:27:29.000000', NULL, 1),
(4301869, 619947, 46885, '<td valign="top">Nice response to the theme, but kindda boring visually</td>', 'Nice response to the theme, but kindda boring visually', '2007-12-08 16:28:49.000000', NULL, 1),
(4301871, 619436, 46885, '<td valign="top">The child out of focus pulls the attention away from the belly, I think.</td>', 'The child out of focus pulls the attention away from the belly, I think.', '2007-12-08 16:30:44.000000', NULL, 1),
(4301876, 619688, 46885, '<td valign="top">Gees, these drops are becoming a commonplace and their abstract shape can be fit into any challenge with no particular meaning in any of them. Great timing, nice lighting colours, but very overused.</td>', 'Gees, these drops are becoming a commonplace and their abstract shape can be fit into any challenge with no particular meaning in any of them. Great timing, nice lighting colours, but very overused.', '2007-12-08 16:34:38.000000', NULL, 1),
(4301885, 619127, 46885, '<td valign="top">Please don''t tell me what to do. Does that semi-concealed writing constitute your response to the theme? What does that bloke in soft focus do, then - just filling the rest of the pixel space?</td>', 'Please don''t tell me what to do. Does that semi-concealed writing constitute your response to the theme? What does that bloke in soft focus do, then - just filling the rest of the pixel space?', '2007-12-08 16:37:32.000000', NULL, 1),
(4301890, 619430, 46885, '<td valign="top">Rather sloppy work, I think. The glare and fittings on the glass are grabbing 50% of my attention whilst meaning nothing, the strange string of speckles is only understandable once I read the title and the couple is so obscured...</td>', 'Rather sloppy work, I think. The glare and fittings on the glass are grabbing 50% of my attention whilst meaning nothing, the strange string of speckles is only understandable once I read the title and the couple is so obscured...', '2007-12-08 16:41:26.000000', NULL, 1),
(4301892, 619940, 46885, '<td valign="top">There''s a bloke. And his trumpet. And for all I see he might as well be silent. Bit more light on the face and his cheeks puffed like there''s no tomorrow might have made me change my mind.</td>', 'There''s a bloke. And his trumpet. And for all I see he might as well be silent. Bit more light on the face and his cheeks puffed like there''s no tomorrow might have made me change my mind.', '2007-12-08 16:43:13.000000', NULL, 1),
(4301896, 619805, 46885, '<td valign="top">Is this how they blink - without lowering their eyelid? Needs some foreword, I think. Great timing, if you were really aiming for that. If you don''t win, it will still have a great use as a poster in some optician clinic.</td>', 'Is this how they blink - without lowering their eyelid? Needs some foreword, I think. Great timing, if you were really aiming for that. If you don''t win, it will still have a great use as a poster in some optician clinic.', '2007-12-08 16:45:07.000000', NULL, 1),
(4301897, 619491, 46885, '<td valign="top">Great landscape, but lose the bloke and submit to some other theme.</td>', 'Great landscape, but lose the bloke and submit to some other theme.', '2007-12-08 16:46:02.000000', NULL, 1),
(4301899, 619444, 46885, '<td valign="top">Takes some thinking, but a very interesting approach. I would have tried tilting the bottle to give some visual hint.</td>', 'Takes some thinking, but a very interesting approach. I would have tried tilting the bottle to give some visual hint.', '2007-12-08 16:47:14.000000', NULL, 1),
(4301901, 617756, 87314, '<td valign="top">Excellent idea and B &amp; W works terrically for me.  Wish her elbow was not cut off.  Also lead in of the instrument might work better if coming in from the corner....<br/> <br/> nice work, jim</td>', 'Excellent idea and B & W works terrically for me.  Wish her elbow was not cut off.  Also lead in of the instrument might work better if coming in from the corner....  nice work, jim', '2007-12-08 16:47:30.000000', NULL, 1),
(4301910, 617898, 46885, '<td valign="top">Nope, I can only see a grossly overprocessed shot.</td>', 'Nope, I can only see a grossly overprocessed shot.', '2007-12-08 16:53:52.000000', NULL, 1),
(4301913, 619467, 46885, '<td valign="top">Mmm... I''d tease the viewer a bit more by including larger lenghts of the flesh</td>', 'Mmm... I''d tease the viewer a bit more by including larger lenghts of the flesh', '2007-12-08 16:54:57.000000', NULL, 1),
(4301916, 619834, 46885, '<td valign="top">Nice approach, but would be great to have a conveyor belt or something more dramatically un-Christmas.</td>', 'Nice approach, but would be great to have a conveyor belt or something more dramatically un-Christmas.', '2007-12-08 16:56:28.000000', NULL, 1),
(4301943, 617702, 76103, '<td valign="top">Nice date in the corner.</td>', 'Nice date in the corner.', '2007-12-08 17:15:54.000000', NULL, 1),
(4301955, 619167, 76103, '<td valign="top">Sorry but I really hate the editing you did on it. It makes the dog look fake, not soft.</td>', 'Sorry but I really hate the editing you did on it. It makes the dog look fake, not soft.', '2007-12-08 17:25:15.000000', NULL, 1),
(4301992, 619565, 85733, '<td valign="top">The black background is a great to frame the picture.</td>', 'The black background is a great to frame the picture.', '2007-12-08 17:42:37.000000', NULL, 1),
(4301997, 618839, 85733, '<td valign="top">The shadow make a difference on the picture, good addition.</td>', 'The shadow make a difference on the picture, good addition.', '2007-12-08 17:43:55.000000', NULL, 1),
(4302005, 619426, 85733, '<td valign="top">Nice macro, with nice transparent colors</td>', 'Nice macro, with nice transparent colors', '2007-12-08 17:47:23.000000', NULL, 1),
(4302010, 618953, 85733, '<td valign="top">Nice sharpness.</td>', 'Nice sharpness.', '2007-12-08 17:49:48.000000', NULL, 1),
(4302197, 619894, 37444, '<td valign="top">This is so precious!</td>', 'This is so precious!', '2007-12-08 19:48:05.000000', NULL, 1),
