(4302500, 619537, 24454, '<td valign="top">She is a blessed little girl!  Kudos to the stay-at-home dad!!!</td>', 'She is a blessed little girl!  Kudos to the stay-at-home dad!!!', '2007-12-09 00:06:20.000000', NULL, 1),
(4302501, 619278, 24454, '<td valign="top">:)   Like a fine Norman Rockwell painting!</td>', ':)   Like a fine Norman Rockwell painting!', '2007-12-09 00:06:46.000000', NULL, 1),
