INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4307615, 617898, 6771, '<td valign="top">the post processing of this (although intentional) is not extremely appealing.  the eyes color is pretty cool, but the rest of the posterization is not as desirable</td>', 'the post processing of this (although intentional) is not extremely appealing.  the eyes color is pretty cool, but the rest of the posterization is not as desirable', '2007-12-11 01:43:01.000000', NULL, 1),
(4307618, 618633, 6771, '<td valign="top">There seems to be something in front of the mask, but cannot make out what.  It appears washed out and needs a little more contrast and punch.</td>', 'There seems to be something in front of the mask, but cannot make out what.  It appears washed out and needs a little more contrast and punch.', '2007-12-11 01:44:22.000000', NULL, 1),
(4307619, 617702, 6771, '<td valign="top">Decent idea, but the interest in the photo is a little low.  I am sure it has been said before, but turning off the date would decrease that distraction.</td>', 'Decent idea, but the interest in the photo is a little low.  I am sure it has been said before, but turning off the date would decrease that distraction.', '2007-12-11 01:45:37.000000', NULL, 1),
(4307622, 619629, 6771, '<td valign="top">This looks like a photo of a poster or screen.  There is not much to judge as a photograph here from how it is represented.</td>', 'This looks like a photo of a poster or screen.  There is not much to judge as a photograph here from how it is represented.', '2007-12-11 01:46:40.000000', NULL, 1),
(4307623, 619477, 6771, '<td valign="top">Nice focus.  Great schematic/stock photo for a vintage HAM radio magazine.</td>', 'Nice focus.  Great schematic/stock photo for a vintage HAM radio magazine.', '2007-12-11 01:47:26.000000', NULL, 1),
(4307625, 619759, 6771, '<td valign="top">The mix of the lighting colors is a bit distracting, though hard to get rid of. Considering it is definitely a long exposure, the movement through it is too fast to even barely make out a boot.  The light coming in to the R upper corner is distracting.</td>', 'The mix of the lighting colors is a bit distracting, though hard to get rid of. Considering it is definitely a long exposure, the movement through it is too fast to even barely make out a boot.  The light coming in to the R upper corner is distracting.', '2007-12-11 01:49:23.000000', NULL, 1),
(4307628, 618538, 6771, '<td valign="top">Nice idea, but fairly boring (sorry).  Trying in a portrait mode may have impacted more with having the arms showing more.  The reddish white balance gives it a dull and muddled look to it.</td>', 'Nice idea, but fairly boring (sorry).  Trying in a portrait mode may have impacted more with having the arms showing more.  The reddish white balance gives it a dull and muddled look to it.', '2007-12-11 01:51:22.000000', NULL, 1),
(4307629, 617764, 6771, '<td valign="top">Even though you got the focus right on to the eyes and give a different perspective of a child trying to crawl (?),  seeing the eyes would have given this much more impact.</td>', 'Even though you got the focus right on to the eyes and give a different perspective of a child trying to crawl (?),  seeing the eyes would have given this much more impact.', '2007-12-11 01:52:25.000000', NULL, 1),
(4307631, 618962, 6771, '<td valign="top">Probably my favorite in the challenge.  I love the way the icicles give this such an eerie feeling. At first glance I thought that this was a frozen bird in a window or a ghoul from Harry Potter.</td>', 'Probably my favorite in the challenge.  I love the way the icicles give this such an eerie feeling. At first glance I thought that this was a frozen bird in a window or a ghoul from Harry Potter.', '2007-12-11 01:56:11.000000', NULL, 1),
(4307633, 619672, 6771, '<td valign="top">One of my faves in the challenge.  Excellent focus on the eyes.  Love the pose/catch of the child and the black background and clothes that frame the face.</td>', 'One of my faves in the challenge.  Excellent focus on the eyes.  Love the pose/catch of the child and the black background and clothes that frame the face.', '2007-12-11 01:57:20.000000', NULL, 1),
(4307635, 619113, 6771, '<td valign="top">Great catch on this one.  Great focus and balancing the mainly high end whites on this shot.</td>', 'Great catch on this one.  Great focus and balancing the mainly high end whites on this shot.', '2007-12-11 01:58:20.000000', NULL, 1),
(4307636, 619565, 6771, '<td valign="top">Great colors and dreamy look of what looks like a geode.  But then again it may be some sea creature.  ???</td>', 'Great colors and dreamy look of what looks like a geode.  But then again it may be some sea creature.  ???', '2007-12-11 01:59:21.000000', NULL, 1),
(4307638, 619752, 6771, '<td valign="top">A fish...a fish...a fish...a fish. Oh where could that fish beeeeeeee.  Great natural colors without wanting to oversaturate it, along with the great focus.</td>', 'A fish...a fish...a fish...a fish. Oh where could that fish beeeeeeee.  Great natural colors without wanting to oversaturate it, along with the great focus.', '2007-12-11 02:00:36.000000', NULL, 1),
(4307640, 619280, 6771, '<td valign="top">I figured this would be done quite a bit, but no worries.  Gotta learn right.  It seems that you did get good focus on the "ghost."  The white balance seems a bit on the warm (red) side.</td>', 'I figured this would be done quite a bit, but no worries.  Gotta learn right.  It seems that you did get good focus on the "ghost."  The white balance seems a bit on the warm (red) side.', '2007-12-11 02:02:10.000000', NULL, 1),
(4307641, 619385, 6771, '<td valign="top">Looks like rice krispies in front of a red light.  Interesting for a few, but not much going on to hold interest and study it longer.</td>', 'Looks like rice krispies in front of a red light.  Interesting for a few, but not much going on to hold interest and study it longer.', '2007-12-11 02:03:09.000000', NULL, 1),
(4307645, 619818, 6771, '<td valign="top">Figured seeing a few photos like this, but learning is what we are here for.  Basic and not alot of interest to hld a viewer very long.  The white balance could be a bit cooler to drop the muddled reddish color.</td>', 'Figured seeing a few photos like this, but learning is what we are here for.  Basic and not alot of interest to hld a viewer very long.  The white balance could be a bit cooler to drop the muddled reddish color.', '2007-12-11 02:04:47.000000', NULL, 1),
